CREATE TRIGGER availability_time_guard BEFORE UPDATE OF time ON slots WHEN OLD.time<>NEW.time AND EXISTS(SELECT 1 FROM order_slots WHERE slot_id=OLD.id) BEGIN SELECT RAISE(ABORT,'BOOKED_TIME_CONFLICT'); END;
